  "plan_name": "feature_engineering_tool_plan",
  "steps": [
    {
      "tool": "group_rare_categories",
      "parameters": {
        "column": "Neighborhood",
        "threshold": 0.02,
        "rare_label": "Other"
      },
      "reasoning": "Neighborhood has 25 categories; grouping rare neighborhoods reduces sparsity before encoding while preserving the most common locations."
    },
    {
      "tool": "encode_categorical",
      "parameters": {
        "column": "Neighborhood",
        "method": "onehot"
      },
      "reasoning": "After rare-category grouping, Neighborhood is a manageable nominal categorical feature and can be one-hot encoded for regression modeling."
    },
    {
      "tool": "create_interaction",
      "parameters": {
        "cols": [
          "GrLivArea",
          "TotalBsmtSF"
        ],
        "operator": "+",
        "new_col": "TotalSF"
      },
      "reasoning": "Combining above-ground living area and basement area creates a total-square-footage signal that is strongly associated with house price."
    },
    {
      "tool": "create_interaction",
      "parameters": {
        "cols": [
          "YrSold",
          "YearBuilt"
        ],
        "operator": "-",
        "new_col": "HouseAgeAtSale"
      },
      "reasoning": "House age at sale is a meaningful numeric derived feature and is safer than using raw year fields alone."
    },
    {
      "tool": "create_binning",
      "parameters": {
        "column": "YearBuilt",
        "n_bins": 5,
        "new_col": "YearBuiltBin",
        "strategy": "quantile"
      },
      "reasoning": "Quantile binning of YearBuilt captures broad construction-era effects while keeping the feature compact and interpretable."
    }
  ]
}

